const draftKey='psmvd-editor-draft';const campaignForm=document.querySelector('#campaignForm'),homepageForm=document.querySelector('#homepageForm');const updateCampaign=()=>{if(!campaignForm)return;const data=Object.fromEntries(new FormData(campaignForm));document.querySelector('#previewTicker').textContent=`${data.code||'CÓDIGO'} · ${data.benefit||'Oferta'}`;document.querySelector('#previewKicker').textContent=(data.name||'Nueva campaña').toUpperCase();document.querySelector('#previewBenefit').textContent=data.benefit||'Oferta';document.querySelector('#previewCondition').textContent=data.condition||'Sumá condiciones';document.querySelector('#previewCode').textContent=data.code||'CÓDIGO';document.querySelector('#previewPeriod').textContent=data.period||'Próximamente';document.querySelector('#campaignState').textContent='Cambios sin guardar'};const updateHomepage=()=>{if(!homepageForm)return;const data=Object.fromEntries(new FormData(homepageForm));document.querySelector('#homePreviewEyebrow').textContent=data.eyebrow||'PHONE STORE MVD';document.querySelector('#homePreviewHeadline').innerHTML=(data.headline||'Tu próximo equipo.').replace('.','.<br>');document.querySelector('#homePreviewSubline').textContent=data.subline||'';document.querySelector('#homePreviewCta').textContent=`${data.cta||'Explorar'} →`;document.querySelector('#homepageState').textContent='Cambios sin guardar'};campaignForm?.addEventListener('input',updateCampaign);homepageForm?.addEventListener('input',updateHomepage);campaignForm?.addEventListener('submit',event=>{event.preventDefault();const all=JSON.parse(localStorage.getItem(draftKey)||'{}');all.campaign=Object.fromEntries(new FormData(campaignForm));localStorage.setItem(draftKey,JSON.stringify(all));document.querySelector('#campaignState').textContent='Borrador guardado';document.querySelector('#campaignNote').textContent='Borrador guardado en este dispositivo. La vista previa está lista para revisar.'});homepageForm?.addEventListener('submit',event=>{event.preventDefault();const all=JSON.parse(localStorage.getItem(draftKey)||'{}');all.homepage=Object.fromEntries(new FormData(homepageForm));localStorage.setItem(draftKey,JSON.stringify(all));document.querySelector('#homepageState').textContent='Borrador guardado';document.querySelector('#homepageNote').textContent='Cambios guardados en este dispositivo. Podés seguir editando o restablecerlos.'});const restore=()=>{const saved=JSON.parse(localStorage.getItem(draftKey)||'{}');for(const [formName,values] of Object.entries(saved)){const current=formName==='campaign'?campaignForm:homepageForm;if(!current)continue;Object.entries(values).forEach(([key,value])=>{const field=current.elements[key];if(field){if(field.type==='checkbox')field.checked=value==='on';else field.value=value}})}updateCampaign();updateHomepage()};document.querySelector('#resetCampaign')?.addEventListener('click',()=>{campaignForm.reset();updateCampaign();document.querySelector('#campaignNote').textContent='Volviste a los valores de la campaña.'});document.querySelector('#resetHomepage')?.addEventListener('click',()=>{homepageForm.reset();updateHomepage();document.querySelector('#homepageNote').textContent='Volviste a los valores originales de portada.'});document.querySelector('#openCampaigns')?.addEventListener('click',()=>openView('offers'));document.querySelector('#newCampaign')?.addEventListener('click',()=>{campaignForm.reset();updateCampaign();document.querySelector('#campaignNote').textContent='Nueva campaña lista para diseñar.'});restore();
